export function score(answers) {
  if (!Array.isArray(answers) || answers.length !== 6 || !answers.every(x => x === 0 || x === 1)) throw new Error('请先完成全部 6 道题。');
  const h = Number(answers[0] === 0) + Number(answers[2] === 1) + Number(answers[4] === 0);
  const p = Number(answers[1] === 0) + Number(answers[3] === 1) + Number(answers[5] === 1);
  const key = h >= 2 ? (p >= 2 ? 'technical' : 'pure') : (p >= 2 ? 'autonomous' : 'reform');
  return { h, p, key };
}
